//#region src/lib/bill-splitting.ts
function splitLines(lines, quantities) {
	const split = [];
	const remaining = [];
	for (const line of lines) {
		const splitQty = Math.max(0, Math.min(line.qty, Math.floor(quantities[line.itemId] ?? 0)));
		if (splitQty > 0) split.push({
			...line,
			qty: splitQty
		});
		if (line.qty > splitQty) remaining.push({
			...line,
			qty: line.qty - splitQty
		});
	}
	return {
		split,
		remaining
	};
}
